{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_15",
      "quote": "To assess SARSCoV-2 positivity rates in offspring, we included cohort studies of pregnant and recently pregnant women who sought hospital care for any reason and had a diagnosis of SARS-CoV-2 infection, and where SARSCoV-2 status was ascertained in the fetus or neonate using RT-PCR (neonatal pharyngeal, rectal, or faecal swabs, neonatal or cord blood, fetal tissue, placental samples, or amniotic fluid) or serological tests (antiSARS-CoV-2 IgM), or both. We defined cohort studies as those that sampled consecutive women, who were followed-up to ascertain the SARS-CoV-2 status of their offspring within the first 30 days after birth. 17 In addition to the cohort studies, we included case series and case reports to assess the timing of motherto-child transmission and likelihood of infection. To evaluate maternal risk factors for offspring SARS-CoV-2 positivity, we included cohort studies of pregnant and recently pregnant women with a diagnosis of SARS-CoV-2 infection that reported on maternal and perinatal risk factors such as maternal severe covid-19, admission to an intensive care unit, and death; timing of exposure to the virus (antenatal v postnatal; third v first or second trimester); intrapartum factors (<37 weeks preterm v term); mode of delivery (caesarean section v vaginal birth); timing of cord clamping (immediate v delayed)); postnatal care (skin-to-skin contact v none; not separated v separated at birth; breastfed versus not breastfed); and SARS-CoV-2 infection status of the offspring.",
      "reason": "The text specifies the study designs (cohort, case series, case reports), participant populations (pregnant and recently pregnant women seeking hospital care), outcomes and how measured (RT-PCR, IgM, sample types), definition of cohort (consecutive sampling, follow-up within 30 days), and which risk-factor comparisons were eligible."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "For this update of the living systematic review, we included studies from searches up to 25 April 2022. No language restrictions were applied. Our searches were coordinated with the EPPI-Centre, the WHO (World Health Organization) Library, and the Cochrane Gynaecology and Fertility group (see supplementary appendix 2). We searched major databases, preprint servers, and websites that serve as repositories for covid-19 studies, including Medline, Embase, Cochrane database, WHO COVID-19 database, Living Overview of the Evidence platform, China National Knowledge Infrastructure (CNKI), and Wanfang databases for studies (cohort, case series, and case report) on SARS-CoV-2 infection in pregnant and recently pregnant women (including after abortion or miscarriage).",
      "reason": "The search description states the date range (up to 25 April 2022), declares no language restrictions, and indicates inclusion of preprint servers/repositories (covering publication/report status)."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishing exclusion because outcomes were not measured from exclusion because outcome results were not reported is present in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "The World Health Organization classification was used to categorise the timing of mother-to-child transmission (in utero, intrapartum, early postnatal).",
      "reason": "The review specifies groups used in syntheses (timing categories: in utero, intrapartum, early postnatal) and links these to the WHO classification used to define comparisons; figures and text (Fig 3) further show these groupings."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_2",
      "quote": "We only included cohort studies for estimating the rates of SARS-CoV-2 positivity in offspring, unlike some of the published systematic reviews, which combined cohort and case-control studies with case series 47-49 or reported positivity in babies as neonatal infection.",
      "reason": "The authors state a notable restriction (using only cohort studies to estimate rates) and provide a rationale contrasting their approach with other reviews, explaining the choice."
    }
  ],
  "confidence": "85"
}

